package in.gridcare.portal.config;
import org.springframework.context.annotation.Configuration;import org.springframework.web.servlet.config.annotation.*;
@Configuration public class CorsConfig implements WebMvcConfigurer{@Override public void addCorsMappings(CorsRegistry r){r.addMapping("/api/**").allowedOriginPatterns("http://localhost:*","http://127.0.0.1:*","file://*").allowedMethods("GET","POST","OPTIONS").allowedHeaders("*");}}